// Verifies the HMAC signature Convex put on this webhook call.
// Wire format: see convex/lib/hmac.ts. Secret comes from the n8n env var
// CONVEX_TO_N8N_SECRET (never hard-coded in the workflow).
const crypto = require('crypto');
const TOLERANCE_S = 300;

const item = $input.first();
const headers = item.json.headers || {};
const secret = $env.CONVEX_TO_N8N_SECRET;
if (!secret) throw new Error('CONVEX_TO_N8N_SECRET is not set in the n8n environment');

// Verify against the exact bytes Convex signed (Webhook node has "Raw Body" on).
let rawBody;
try {
  rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  rawBody = JSON.stringify(item.json.body ?? {});
}

const reject = (reason) => [{ json: { valid: false, reason } }];
const signature = String(headers['x-lendloop-signature'] || '');
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const nonce = String(headers['x-lendloop-nonce'] || '');
if (!signature || !timestamp || !nonce) return reject('missing_headers');
if (!/^\d{1,12}$/.test(timestamp)) return reject('bad_timestamp');
if (!/^[A-Za-z0-9_-]{16,128}$/.test(nonce)) return reject('bad_nonce');

const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - Number(timestamp)) > TOLERANCE_S) return reject('stale_timestamp');

const expected = 'v1=' + crypto.createHmac('sha256', secret)
  .update(`${timestamp}.${nonce}.${rawBody}`).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature.trim());
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject('bad_signature');

// Replay protection: each nonce is accepted once inside the window.
const store = $getWorkflowStaticData('global');
store.nonces = store.nonces || {};
store.processed = store.processed || {};
for (const [n, exp] of Object.entries(store.nonces)) if (exp < now) delete store.nonces[n];
for (const [k, exp] of Object.entries(store.processed)) if (exp < now) delete store.processed[k];
if (store.nonces[nonce]) return reject('replayed_nonce');
store.nonces[nonce] = now + 2 * TOLERANCE_S;

const payload = JSON.parse(rawBody);
// Idempotency: Convex retries reuse the same eventId; skip ones already handled.
const duplicate = Boolean(store.processed[payload.eventId]);
return [{ json: { valid: true, duplicate, payload } }];

