// Remember the eventId only after the email went out, so a Convex retry of a
// failed delivery is processed again, but a retry of a successful one is not.
const store = $getWorkflowStaticData('global');
store.processed = store.processed || {};
const eventId = $('Verify HMAC signature').first().json.payload.eventId;
store.processed[eventId] = Math.floor(Date.now() / 1000) + 7 * 24 * 3600;
return [{ json: { ok: true, eventId } }];
